  function gridColumns(key){const definition=grids.get(key);if(!definition)return;const config=gridConfig(key);openModal({title:'Customize columns',eyebrow:'View settings',submitText:'Apply view',body:'<div class="rb-column-options">'+definition.columns.filter(c=>c.id!=='select').map(c=>'<label><input type="checkbox" name="column" value="'+c.id+'" '+((config.columns?config.columns.includes(c.id):!c.optional)?'checked':'')+'> '+esc(c.label)+'</label>').join('')+'</div>',onSubmit:form=>{const chosen=form.getAll('column');if(!chosen.length){toast('Keep at least one column visible');return;}config.columns=['select',...chosen];config.page=1;closeModal();render();}});}
